function j = ColburnFactor(h, l, s, t, Re)
    % Colburn factor calculation for laminar and turbulent range
    if (Re >= 300 && Re <= 800)
        j = 0.661 * (Re^(-0.651)) * ((s/h)^(-0.343)) * ((t/s)^(-0.538)) * ((t/l)^(0.305));
